function OilCoachScreen({ vehicle, scenario }) {
  const rules = matchAdaptiveRules(scenario.adaptive_rules, vehicle);
  const [i, setI] = useState(0);
  const step = applyVariants(scenario.steps[i], vehicle);
  const asset = scenario.visual_assets.find(a => a.key === step.visual_asset_key);

  return (
    <SafeAreaView>
      <Progress segments={scenario.steps.length} index={i} />
      <CoachMedia type={step.visual_type} src={asset?.src} poster={asset?.poster} />
      <Text style={title}>{step.title}</Text>
      <Text style={body}>{injectCoachNotes(step.description, rules)}</Text>
      {step.safety_warning && <SafetyBanner text={step.safety_warning} />}
      <ButtonRow
        buttons={step.action_buttons}
        onPress={(btn) => handleCoachAction(btn, { setI, vehicle, scenario })}
      />
      <VoiceCoachChip onPress={startLiveRepairMode} />
    </SafeAreaView>
  );
}

// handleCoachAction: next_step → i++; skip_to → findIndex; open_chat → router.chat(payload);
